with flattened as (select id, currency, explode_outer(tier_prices) as val from price_tiers), enriched as (select id, currency, stddev_samp(val) over (partition by currency) currency_stddev_samp_val from flattened where val < 63), filtered as (select *, round(currency_stddev_samp_val * 1.07, 2) currency_stddev_samp_val_scaled, round(currency_stddev_samp_val * 0.85, 2) currency_stddev_samp_val_adjusted from enriched where currency = 'USD'), cleaned as (select *, cast(currency_stddev_samp_val_adjusted as int) currency_stddev_samp_val_adjusted_int from filtered where currency = 'EUR') select id, currency, currency_stddev_samp_val, currency_stddev_samp_val_scaled, currency_stddev_samp_val_adjusted from cleaned
